WITH "m0" AS ( DELETE FROM "public"."mutation_item" AS "s" WHERE ( true AND ( ( true AND ( "s"."id" = $1 ) ) ) AND ( "s"."owner_id" = $2 ) ) RETURNING "s" AS "t0" , "s"."ctid" AS "k0" ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ), "w0" AS (SELECT "s" .* FROM "public"."mutation_item" AS "s" WHERE NOT EXISTS ( SELECT 1 FROM "m0" WHERE "m0"."k0" = "s"."ctid" ) ) SELECT (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "c1"."j" AS "owner" ) AS "%")) FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t1"."name" AS "name" , "c1"."j" AS "items" , "c2"."j" AS "items_aggregate" ) AS "%")) AS "j" FROM ( SELECT "s".* FROM "public"."mutation_author" AS "s" WHERE true AND "s"."id" = "t0"."owner_id" AND ( ( true AND ( ( true ) ) AND ( "s"."id" = $3 ) ) ) LIMIT 1 ) AS "t1" LEFT JOIN LATERAL (SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t2"."id" AS "id" , "t2"."score" AS "score" ) AS "%")) ORDER BY "t2"."id" ASC NULLS LAST ), '[]') AS "j" FROM ( SELECT "s".* FROM "w0" AS "s" WHERE true AND "s"."owner_id" = "t1"."id" AND ( ( true AND ( ( true ) ) AND ( "s"."score" <= $4 ) ) ) ORDER BY "s"."id" ASC NULLS LAST ) AS "t2" ) AS "c1" ON true LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT row_to_json((SELECT "%" FROM (SELECT count( "t2" .*) AS "count" , row_to_json((SELECT "%" FROM (SELECT sum( "t2"."score" ) AS "score" ) AS "%")) AS "sum" ) AS "%")) AS "aggregate" ) AS "%")) AS "j" FROM ( SELECT "s".* FROM "w0" AS "s" WHERE true AND "s"."owner_id" = "t1"."id" AND ( ( true AND ( ( true ) ) AND ( "s"."score" <= $5 ) ) ) ) AS "t2" ) AS "c2" ON true ) AS "c1" ON true )
